import math

def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    return n > 0 and (n & (n - 1) == 0)

def test_n_equals_4(max_x=20):
    solutions = []
    print(f"--- Testing n=4 for x from 5 to {max_x} where x mod 3 != 1 ---")

    for x in range(5, max_x + 1):
        if x % 3 == 1:
            print(f"Skipping x={x} because {x} mod 3 = 1.")
            continue

        # Calculate N = x^4 + x - 2
        N = x**4 + x - 2

        if is_power_of_two(N):
            k = N.bit_length() - 1
            solutions.append((x, 4, k))
            print(f"\n*** SOLUTION FOUND ***")
            print(f"For x={x}, N = {N} = 2^{k}")
            print(f"Tuple: ({x}, 4, {k})\n")
        else:
            # print(f"x={x}: N = {N} (Not a power of 2)") # Too much output, only print if successful or if we need debugging
            pass

    return solutions

solutions = test_n_equals_4(max_x=20)
print("\n--- Summary ---")
if solutions:
    print("Found solutions:", solutions)
else:
    print("No solutions found in the tested range.")

