def check_n3(m):
    # x = 2^m + 1
    # LHS = (2^m + 1)^3 + 2^m - 1

    x = (2**m) + 1
    lhs = x**3 + (2**m) - 1

    if lhs <= 0:
        return None

    # Check if lhs is a power of 2
    is_power_of_two = (lhs > 0) and ((lhs & (lhs - 1)) == 0)

    if is_power_of_two:
        k = lhs.bit_length() - 1
        return (x, 3, k)
    else:
        return None

solutions = []
# Check m up to 10, which corresponds to x up to 1025
for m in range(1, 11): 
    sol = check_n3(m)
    if sol:
        solutions.append(sol)
    else:
        # Since the magnitude grows extremely fast, if we fail for a larger m, 
